WITH parsed AS (SELECT id, created_at, coupon_codes, TRANSFORM(items, li -> li.product_id) AS product_ids, ship_to.zip AS ship_zip, attributes['gift'] AS gift, TRY_CAST(attributes['weight_kg'] AS DOUBLE) AS weight_kg, ARRAY_CONTAINS(MAP_KEYS(attributes), 'gift') AS has_gift FROM carts) SELECT *, CUME_DIST() OVER (ORDER BY weight_kg DESC) AS weight_kg_cume_dist, SUM(weight_kg) OVER (ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS weight_kg_sum_15m FROM parsed;
